alter table public.tasks
  add column if not exists demo_feed_order integer;

create index if not exists tasks_demo_feed_order_idx
  on public.tasks(demo_feed_order);

with demo_tasks (
  demo_source_id,
  demo_feed_order,
  requester_name,
  title,
  prompt,
  task_type,
  content_idea,
  image_path,
  why_human,
  response_type,
  response_options
) as (
  values
    (1, 2, 'eBay', 'Is this listing photo misleading', 'Is this listing photo misleading?', 'content_safety', 'Marketplace listing photo showing a luxury handbag on a plain background with small defects hidden by lighting.', '/demo/feed-cards/images/1_ebay.png', 'Humans notice visual context and seller intent that automated checks often miss.', 'thumbs', array['thumbs_up', 'thumbs_down']::text[]),
    (2, 49, 'TikTok', 'Is this thumbnail too sexually suggestive for teen users', 'Is this thumbnail too sexually suggestive for teen users?', 'content_safety', 'Short video thumbnail of a creator in swimwear with ambiguous pose and bold reaction text.', '/demo/feed-cards/images/2_tiktok.png', 'The decision depends on cultural context, pose, and platform norms.', 'binary', array['Yes', 'No']::text[]),
    (3, 9, 'Discord', 'Does this message contain subtle harassment', 'Does this message contain subtle harassment?', 'content_safety', 'Chat screenshot where a user repeatedly makes polite but targeted comments about another user.', '/demo/feed-cards/images/3_discord.png', 'Harassment can be indirect and pattern-based, which makes human judgment valuable.', 'binary', array['Yes', 'No']::text[]),
    (4, 25, 'Roblox', 'Is this character design safe for all audiences', 'Is this character design safe for all audiences?', 'content_safety', 'Fantasy avatar skin with exaggerated armor, fake blood, and dramatic lighting.', '/demo/feed-cards/images/4_roblox.png', 'A verified person can judge whether stylized violence feels playful or intense.', 'thumbs', array['thumbs_up', 'thumbs_down']::text[]),
    (5, 58, 'DoorDash', 'Does this image show spoiled or unsafe food', 'Does this image show spoiled or unsafe food?', 'content_safety', 'Restaurant review photo of a delivered meal with odd coloring and damaged packaging.', '/demo/feed-cards/images/5_doordash.png', 'Food safety perception depends on visual nuance and real-world expectations.', 'binary', array['Yes', 'No']::text[]),
    (6, 15, 'Twitch', 'Should this preview be age-restricted', 'Should this preview be age-restricted?', 'content_safety', 'Livestream preview from a party scene with low light, drinks, and crowded framing.', '/demo/feed-cards/images/6_twitch.png', 'Age gating requires contextual interpretation beyond object detection.', 'binary', array['Yes', 'No']::text[]),
    (7, 21, 'Meta Ads', 'Is this ad making an unrealistic health claim', 'Is this ad making an unrealistic health claim?', 'content_safety', 'Social ad creative for a supplement with before-and-after imagery and bold promise text.', '/demo/feed-cards/images/7_meta-ads.png', 'Humans can identify implied promises and misleading presentation.', 'binary', array['Yes', 'No']::text[]),
    (8, 44, 'Khan Academy', 'Does this image reveal personal information', 'Does this image reveal personal information?', 'content_safety', 'Student-uploaded worksheet photo with names, school header, and handwritten notes visible.', '/demo/feed-cards/images/8_khan-academy.png', 'Privacy risk depends on what is legible and how identifying it feels.', 'binary', array['Yes', 'No']::text[]),
    (9, 6, 'Strava', 'Is this image acceptable for a fitness community feed', 'Is this image acceptable for a fitness community feed?', 'content_safety', 'Fitness community progress photo cropped around torso with gym mirror background.', '/demo/feed-cards/images/9_strava.png', 'The answer depends on community standards, framing, and intent.', 'thumbs', array['thumbs_up', 'thumbs_down']::text[]),
    (10, 27, 'Citizen', 'Is this image too graphic for public display', 'Is this image too graphic for public display?', 'content_safety', 'Street incident photo showing an aftermath scene with emergency workers in the background.', '/demo/feed-cards/images/10_citizen.png', 'A person can weigh public value against emotional impact.', 'binary', array['Yes', 'No']::text[]),
    (11, 11, 'Reddit', 'Is the joke hateful or just edgy', 'Is the joke hateful or just edgy?', 'content_safety', 'Meme image using a stereotype-adjacent joke and reaction face.', '/demo/feed-cards/images/11_reddit.png', 'Humor moderation needs cultural and contextual reading.', 'choice_text', array['Hateful', 'Edgy', 'Unclear']::text[]),
    (12, 28, 'YouTube Kids', 'Is this content child-safe', 'Is this content child-safe?', 'content_safety', 'Toy review photo featuring a child holding a product in a bedroom setting.', '/demo/feed-cards/images/12_youtube-kids.png', 'Humans can detect privacy, safety, and appropriateness signals together.', 'thumbs', array['thumbs_up', 'thumbs_down']::text[]),
    (13, 29, 'Etsy', 'Does this look like a valid storefront photo', 'Does this look like a valid storefront photo?', 'content_safety', 'Seller verification photo of a storefront with handwritten sign and partial street view.', '/demo/feed-cards/images/13_etsy.png', 'Authenticity checks benefit from real-world visual common sense.', 'binary', array['Yes', 'No']::text[]),
    (14, 54, 'Reuters', 'Is this image newsworthy or unnecessarily graphic', 'Is this image newsworthy or unnecessarily graphic?', 'content_safety', 'Protest image with smoke, police line, and a partially injured person in the frame.', '/demo/feed-cards/images/14_reuters.png', 'Editorial judgment requires balancing relevance, dignity, and shock value.', 'choice_text', array['Newsworthy', 'Too graphic', 'Unclear']::text[]),
    (15, 4, 'Canva', 'What emotion does this image communicate first', 'What emotion does this image communicate first?', 'sentiment_judgment', 'Generated ad image for a productivity app with a person alone at night beside a glowing laptop.', '/demo/feed-cards/images/15_canva.png', 'Humans are better at reading emotional first impressions.', 'choice_text', array['Calm', 'Stress', 'Ambition', 'Loneliness']::text[]),
    (16, 32, 'Intercom', 'Is the customer angry, confused, or neutral', 'Is the customer angry, confused, or neutral?', 'sentiment_judgment', 'Customer support screenshot where a user writes short replies with punctuation and one emoji.', '/demo/feed-cards/images/16_intercom.png', 'Tone is often encoded in phrasing, timing, and subtle wording.', 'choice_text', array['Angry', 'Confused', 'Neutral']::text[]),
    (17, 10, 'Webflow', 'Does this feel trustworthy', 'Does this feel trustworthy?', 'sentiment_judgment', 'Landing page hero for a new B2B SaaS showing dashboard metrics and a founder quote.', '/demo/feed-cards/images/17_webflow.png', 'Trust is a human perception shaped by copy, layout, and credibility cues.', 'rating', array['1', '2', '3', '4', '5']::text[]),
    (18, 30, 'Zendesk', 'Does this reply sound too aggressive', 'Does this reply sound too aggressive?', 'sentiment_judgment', 'Email draft screenshot responding to a delayed refund request with concise formal language.', '/demo/feed-cards/images/18_zendesk.png', 'A verified human can judge tone before a company sends it.', 'binary', array['Yes', 'No']::text[]),
    (19, 13, 'Instagram', 'Is the tone authentic or sponsored-feeling', 'Is the tone authentic or sponsored-feeling?', 'sentiment_judgment', 'Influencer post with product placement, casual caption, and discount mention.', '/demo/feed-cards/images/19_instagram.png', 'Authenticity is a taste and trust signal that humans read quickly.', 'choice_text', array['Authentic', 'Sponsored-feeling', 'Unclear']::text[]),
    (20, 31, 'App Store', 'Is this feedback positive, negative, or mixed', 'Is this feedback positive, negative, or mixed?', 'sentiment_judgment', 'App store review screenshot praising one feature while complaining about setup friction.', '/demo/feed-cards/images/20_app_store.png', 'Nuanced sentiment often contains both praise and frustration.', 'choice_text', array['Positive', 'Negative', 'Mixed']::text[]),
    (21, 39, 'Stack Overflow', 'Is this disagreement constructive', 'Is this disagreement constructive?', 'sentiment_judgment', 'Forum comment disagreeing with another user while offering sources and pointed language.', '/demo/feed-cards/images/21_stack_overflow.png', 'Constructiveness depends on tone, evidence, and perceived intent.', 'thumbs', array['thumbs_up', 'thumbs_down']::text[]),
    (22, 37, 'LinkedIn', 'Does this feel senior-level at first glance', 'Does this feel senior-level at first glance?', 'sentiment_judgment', 'Candidate portfolio screenshot with project cards, short bio, and visual hierarchy.', '/demo/feed-cards/images/22_linkedin.png', 'Hiring impressions involve judgment about polish, clarity, and confidence.', 'rating', array['1', '2', '3', '4', '5']::text[]),
    (23, 53, 'OpenAI', 'Does this answer feel confident but wrong', 'Does this answer feel confident but wrong?', 'sentiment_judgment', 'AI answer screenshot with confident explanation, citations, and a subtle factual contradiction.', '/demo/feed-cards/images/23_openai.png', 'Humans can flag suspicious confidence and coherence gaps.', 'binary', array['Yes', 'No']::text[]),
    (24, 20, 'Airbnb', 'Does the caption match the image vibe', 'Does the caption match the image vibe?', 'sentiment_judgment', 'Hotel photo with caption promising a peaceful luxury stay despite a busy street view.', '/demo/feed-cards/images/24_airbnb.png', 'Humans compare promise, mood, and visual evidence naturally.', 'thumbs', array['thumbs_up', 'thumbs_down']::text[]),
    (25, 17, 'Shopify', 'Would this answer resolve your issue', 'Would this answer resolve your issue?', 'sentiment_judgment', 'Chatbot answer to a billing issue with apology, steps, and a missing direct solution.', '/demo/feed-cards/images/25_shopify.png', 'Resolution quality is best judged from a user''s lived perspective.', 'thumbs', array['thumbs_up', 'thumbs_down']::text[]),
    (26, 24, 'Duolingo', 'Is this explanation visually clear', 'Is this explanation visually clear?', 'sentiment_judgment', 'Lesson illustration explaining photosynthesis with arrows, labels, and a simplified plant diagram.', '/demo/feed-cards/images/26_duolingo.png', 'Humans can judge whether an educational visual actually makes sense.', 'rating', array['1', '2', '3', '4', '5']::text[]),
    (27, 14, 'Notion', 'Which logo is more memorable', 'Which logo is more memorable?', 'qualitative_feedback', 'Two logo concepts for a privacy-first notes app shown side by side on a phone mockup.', '/demo/feed-cards/images/27_notion.png', 'Brand recall is a fast human preference signal.', 'choice_number', array['1', '2']::text[]),
    (28, 63, 'Revolut', 'Which color fits a finance app best', 'Which color fits a finance app best?', 'qualitative_feedback', 'Finance app mockup with three alternate accent color treatments on cards and CTA buttons.', '/demo/feed-cards/images/28_revolut.png', 'Color trust signals vary by context and human expectation.', 'choice_text', array['Blue', 'Yellow', 'Red']::text[]),
    (29, 61, 'Linear', 'What is the clearest CTA', 'What is the clearest CTA?', 'qualitative_feedback', 'Three onboarding screen variants with different CTA labels under the same product promise.', '/demo/feed-cards/images/29_linear.png', 'Humans can tell which action feels easiest and least ambiguous.', 'choice_number', array['1', '2', '3']::text[]),
    (30, 7, 'Huel', 'Which packaging feels more premium', 'Which packaging feels more premium?', 'qualitative_feedback', 'Two packaging designs for a premium protein snack with different typography and photography.', '/demo/feed-cards/images/30_huel.png', 'Premium perception is subjective and visually contextual.', 'choice_number', array['1', '2']::text[]),
    (31, 26, 'Worldcoin', 'Does this screen feel safe to continue', 'Does this screen feel safe to continue?', 'qualitative_feedback', 'Verification screen asking users to connect a wallet, with security copy and icon treatment.', '/demo/feed-cards/images/31_worldcoin.png', 'Trust around sensitive actions depends heavily on human perception.', 'thumbs', array['thumbs_up', 'thumbs_down']::text[]),
    (32, 38, 'Nike Training Club', 'Which image would make you tap', 'Which image would make you tap?', 'qualitative_feedback', 'Three workout card images showing different trainers, lighting, and exercise framing.', '/demo/feed-cards/images/32_nike_training_club.png', 'Tap appeal is a real user instinct rather than a purely visual metric.', 'choice_number', array['1', '2', '3']::text[]),
    (33, 22, 'Stripe', 'Is the price presentation clear', 'Is the price presentation clear?', 'qualitative_feedback', 'Pricing page screenshot with monthly cost, fee disclosure, and primary CTA.', '/demo/feed-cards/images/33_stripe.png', 'Humans can spot confusion and perceived hidden costs.', 'thumbs', array['thumbs_up', 'thumbs_down']::text[]),
    (34, 3, 'Spotify', 'Which cover feels most clickable', 'Which cover feels most clickable?', 'qualitative_feedback', 'Three album cover options for an indie electronic single with different visual moods.', '/demo/feed-cards/images/34_spotify.png', 'Music discovery relies on taste, mood, and curiosity.', 'choice_number', array['1', '2', '3']::text[]),
    (35, 36, 'Strava', 'Which headline is easiest to understand', 'Which headline is easiest to understand?', 'qualitative_feedback', 'Event poster with three headline treatments for a city running challenge.', '/demo/feed-cards/images/35_strava.png', 'Clarity is best validated by real first-pass comprehension.', 'choice_number', array['1', '2', '3']::text[]),
    (36, 34, 'Ada Health', 'Does this copy feel reassuring', 'Does this copy feel reassuring?', 'qualitative_feedback', 'Health app empty state explaining that no symptoms have been logged yet.', '/demo/feed-cards/images/36_ada-health.png', 'Medical-adjacent UX needs human sensitivity and tone judgment.', 'rating', array['1', '2', '3', '4', '5']::text[]),
    (37, 56, 'Amazon', 'Which badge best signals eco-friendly', 'Which badge best signals eco-friendly?', 'qualitative_feedback', 'Three product badge designs using leaf, recycled, and verified-check motifs.', '/demo/feed-cards/images/37_amazon.png', 'Eco claims need intuitive visual trust from real consumers.', 'choice_text', array['Leaf', 'Recycled', 'Verified']::text[]),
    (38, 41, 'Epic Games', 'Is the next action obvious', 'Is the next action obvious?', 'qualitative_feedback', 'Mobile game mission screen with reward, timer, and next action button.', '/demo/feed-cards/images/38_epic_games.png', 'Game UX depends on immediate human comprehension under attention pressure.', 'thumbs', array['thumbs_up', 'thumbs_down']::text[]),
    (39, 51, 'Coursera', 'Which design feels more credible', 'Which design feels more credible?', 'qualitative_feedback', 'Two certificate designs for an online course completion credential.', '/demo/feed-cards/images/39_coursera.png', 'Credibility is a social perception signal humans evaluate quickly.', 'choice_number', array['1', '2']::text[]),
    (40, 18, 'Behance', 'Which profile looks more professional', 'Which profile looks more professional?', 'qualitative_feedback', 'Two creator profile layouts with bio, metrics, social proof, and portfolio preview.', '/demo/feed-cards/images/40_behance.png', 'Professionalism is a holistic impression across layout and content.', 'choice_number', array['1', '2']::text[]),
    (41, 64, 'Google Search', 'Which result best matches the query', 'Which result best matches the query?', 'qualitative_feedback', 'Search results page for a query about beginner-friendly tax software with three highlighted results.', '/demo/feed-cards/images/41_google_search.png', 'Search relevance depends on intent, not just keyword overlap.', 'choice_number', array['1', '2', '3']::text[]),
    (42, 42, 'Google Maps', 'Which photo should be the cover image', 'Which photo should be the cover image?', 'qualitative_feedback', 'Three local place photos for a cafe: storefront, latte closeup, and seating area.', '/demo/feed-cards/images/42_google_maps.png', 'A human can choose the image that best sets user expectations.', 'choice_number', array['1', '2', '3']::text[]),
    (43, 59, 'Arbitrum DAO', 'Should this proposal move to community vote', 'Should this proposal move to community vote?', 'one_human_decision', 'Governance proposal graphic summarizing a small grant request and community benefit.', '/demo/feed-cards/images/43_arbitrum_dao.png', 'Verified one-human input helps make lightweight governance sybil-resistant.', 'thumbs', array['thumbs_up', 'thumbs_down']::text[]),
    (44, 48, 'Gitcoin', 'Which applicant summary feels more relevant', 'Which applicant summary feels more relevant?', 'one_human_decision', 'Two grant applicant summary cards with problem statement, traction, and requested amount.', '/demo/feed-cards/images/44_gitcoin.png', 'Human judgment can prioritize relevance where metrics are incomplete.', 'choice_number', array['1', '2']::text[]),
    (45, 35, 'Change.org', 'Is this political claim understandable', 'Is this political claim understandable?', 'one_human_decision', 'Campaign poster explaining a local policy claim with chart and short slogan.', '/demo/feed-cards/images/45_change_org.png', 'Civic communication needs real comprehension checks from verified people.', 'thumbs', array['thumbs_up', 'thumbs_down']::text[]),
    (46, 23, 'Layer3', 'Is this task instruction clear enough to complete', 'Is this task instruction clear enough to complete?', 'one_human_decision', 'Task brief screenshot with objective, acceptance criteria, reward, and deadline.', '/demo/feed-cards/images/46_layer3.png', 'Workers can quickly identify ambiguity before a bounty goes live.', 'thumbs', array['thumbs_up', 'thumbs_down']::text[]),
    (47, 45, 'Hugging Face', 'Which label best describes the image', 'Which label best describes the image?', 'one_human_decision', 'Image labeling task showing a product photo with possible labels below it.', '/demo/feed-cards/images/47_hugging_face.png', 'Training data improves when ambiguous labels are checked by real humans.', 'choice_text', array['Backpack', 'Handbag', 'Messenger bag', 'Unclear']::text[]),
    (48, 52, 'Anthropic', 'Which answer is more helpful', 'Which answer is more helpful?', 'one_human_decision', 'Side-by-side AI answers to the same support question, one concise and one detailed.', '/demo/feed-cards/images/48_anthropic.png', 'AI evaluation requires human preference on usefulness and clarity.', 'choice_number', array['1', '2']::text[]),
    (49, 65, 'Coca-Cola', 'Which flavor name fits the design best', 'Which flavor name fits the design best?', 'one_human_decision', 'Beverage concept image with can design, color palette, and three flavor name options.', '/demo/feed-cards/images/49_coca_cola.png', 'Naming is taste-based and benefits from fast consumer feedback.', 'choice_text', array['Citrus Rush', 'Golden Spark', 'Sunburst']::text[]),
    (50, 55, 'World App', 'Which icon would you trust more in World App', 'Which icon would you trust more in World App?', 'one_human_decision', 'Three mini app icon concepts shown inside a World App-style grid.', '/demo/feed-cards/images/50_world_app.png', 'This directly tests World-native user trust with verified human votes.', 'choice_number', array['1', '2', '3']::text[]),
    (51, 43, 'OpenAI', 'Which answer describes the image more accurately', 'Which answer describes the image more accurately?', 'one_human_decision', 'Side-by-side multimodal model answers describing the same messy kitchen photo with small factual differences.', '/demo/feed-cards/images/51_openai.png', 'Verified humans can catch subtle visual hallucinations in AI training data.', 'choice_number', array['1', '2']::text[]),
    (52, 5, 'Scale AI', 'Which annotation set is most accurate', 'Which annotation set is most accurate?', 'one_human_decision', 'Street scene image with bounding boxes around vehicles, cyclists, pedestrians, and traffic signs.', '/demo/feed-cards/images/52_scale_ai.png', 'Autonomous and vision datasets need human checks for edge-case labeling.', 'choice_number', array['1', '2', '3']::text[]),
    (53, 62, 'Hugging Face', 'Which label should be used for training', 'Which label should be used for training?', 'one_human_decision', 'Image of a niche object with four candidate dataset labels below it.', '/demo/feed-cards/images/53_hugging_face.png', 'High-quality labels often require common sense beyond model confidence.', 'choice_text', array['Camping stove', 'Portable speaker', 'Projector', 'Unclear']::text[]),
    (54, 46, 'Anthropic', 'Which reply is more empathetic', 'Which reply is more empathetic?', 'sentiment_judgment', 'Two AI assistant replies to a frustrated user asking for help after a failed payment.', '/demo/feed-cards/images/54_anthropic.png', 'Human preference data captures tone and helpfulness better than automatic metrics.', 'choice_number', array['1', '2']::text[]),
    (55, 12, 'Meta AI', 'Should this image be blocked from training data', 'Should this image be blocked from training data?', 'content_safety', 'AI-generated image prompt result with an ambiguous medical before-and-after claim in the visual.', '/demo/feed-cards/images/55_meta-ai.png', 'Safety datasets need humans to identify risky implicit claims.', 'binary', array['Yes', 'No']::text[]),
    (56, 57, 'Google DeepMind', 'Is the reasoning correct', 'Is the reasoning correct?', 'one_human_decision', 'Math reasoning trace screenshot with a final answer and one potentially flawed intermediate step highlighted.', '/demo/feed-cards/images/56_google_deepmind.png', 'Training evals need humans to judge reasoning, not just final answers.', 'binary', array['Yes', 'No']::text[]),
    (57, 40, 'Perplexity', 'Which citation best supports the answer', 'Which citation best supports the answer?', 'one_human_decision', 'AI answer with three cited snippets shown underneath, where one citation may not support the claim.', '/demo/feed-cards/images/57_perplexity.png', 'Retrieval training depends on human relevance judgments.', 'choice_number', array['1', '2', '3']::text[]),
    (58, 19, 'Runway', 'Which output looks most realistic', 'Which output looks most realistic?', 'qualitative_feedback', 'Three generated video stills for the same prompt, showing different motion realism and artifact levels.', '/demo/feed-cards/images/58_runway.png', 'Generative media models need human taste and artifact detection.', 'choice_number', array['1', '2', '3']::text[]),
    (59, 47, 'Mistral AI', 'Is the extracted total correct', 'Is the extracted total correct?', 'one_human_decision', 'OCR extraction preview from a photographed receipt with item names, prices, and total amount.', '/demo/feed-cards/images/59_mistral.png', 'Document AI training needs humans to verify messy real-world OCR.', 'binary', array['Yes', 'No']::text[]),
    (60, 8, 'Character.AI', 'Is this response supportive enough', 'Is this response supportive enough?', 'sentiment_judgment', 'Chatbot conversation screenshot where the assistant responds to a vulnerable emotional message.', '/demo/feed-cards/images/60_character-ai.png', 'AI companion training requires human judgment on emotional safety and care.', 'rating', array['1', '2', '3', '4', '5']::text[]),
    (61, 50, 'OpenAI', 'Is the highlighted claim supported by the source', 'Is the highlighted claim supported by the source?', 'one_human_decision', 'Side-by-side screenshots of an AI answer and the original source document snippet, with one highlighted claim about product return policy that may be unsupported by the source.', '/demo/feed-cards/images/61_openai.png', 'Grounded AI training needs real humans to catch subtle hallucinations that look plausible but are not actually supported by evidence.', 'binary', array['Yes', 'No']::text[]),
    (62, 16, 'Anthropic', 'Which response is safer for the user', 'Which response is safer for the user?', 'content_safety', 'AI assistant reply to a teenager asking about extreme weight loss, shown with a safety rubric sidebar and two suggested rewritten responses.', '/demo/feed-cards/images/62_anthropic.png', 'Safety tuning for assistants depends on human judgment about care, risk, and whether advice could enable harm.', 'choice_number', array['1', '2']::text[]),
    (63, 1, 'Tesla AI', 'Which annotation set is safer for autonomous driving training', 'Which annotation set is safer for autonomous driving training?', 'one_human_decision', 'Dashcam frame from a rainy city intersection with glare, a cyclist partly hidden behind a delivery van, a pedestrian near the curb, and two competing object-label overlays.', '/demo/feed-cards/images/63_tesla_ai.png', 'Edge-case perception datasets need humans to reason about occlusion, intent, and safety-critical ambiguity beyond bounding box confidence.', 'choice_number', array['1', '2']::text[]),
    (64, 60, 'Runway', 'Which image should be kept for model training', 'Which image should be kept for model training?', 'qualitative_feedback', 'Three generated product-ad stills for the same sneaker prompt, where one has warped laces, one has unnatural hand placement, and one looks clean but slightly less dramatic.', '/demo/feed-cards/images/64_runway.png', 'Generative image models improve from human preference signals that weigh artifacts, realism, composition, and commercial usefulness together.', 'choice_number', array['1', '2', '3']::text[]),
    (65, 33, 'Mistral AI', 'Does the AI reply fully address the user''s concern', 'Does the AI reply fully address the user''s concern?', 'sentiment_judgment', 'Customer support conversation where a user politely reports being double-charged, includes a screenshot of the invoice, and the AI draft reply apologizes but may miss the urgency.', '/demo/feed-cards/images/65_mistral-ai.png', 'Customer-support AI training needs humans to judge whether a response actually resolves the emotional and practical issue, not just whether it sounds polite.', 'choice_text', array['Yes', 'Partially', 'No']::text[])
)
insert into public.tasks (
  demo_source_id,
  requester_name,
  title,
  prompt,
  task_type,
  input_payload,
  response_schema,
  reward_amount,
  max_responses,
  status,
  demo_feed_order
)
select
  demo_source_id,
  requester_name,
  title,
  prompt,
  task_type,
  jsonb_build_object(
    'company', requester_name,
    'content_idea', content_idea,
    'image_path', image_path,
    'why_human', why_human
  ),
  jsonb_build_object(
    'type', response_type,
    'options', to_jsonb(response_options)
  ),
  0.01,
  100,
  'open',
  demo_feed_order
from demo_tasks
on conflict (demo_source_id) do update set
  requester_name = excluded.requester_name,
  title = excluded.title,
  prompt = excluded.prompt,
  task_type = excluded.task_type,
  input_payload = excluded.input_payload,
  response_schema = excluded.response_schema,
  reward_amount = excluded.reward_amount,
  max_responses = excluded.max_responses,
  status = excluded.status,
  demo_feed_order = excluded.demo_feed_order,
  updated_at = now();
